-- Contenus 1 et 2 : dhikr du matin et du soir, après la prière, du sommeil et du réveil (74 entrées).
-- Insérés NON validés (reviewed_at NULL) et NON affichés (enabled false) : rien n'apparaît chez les membres avant relecture
-- et validation dans Admin → Athkar. Idempotent : un dhikr déjà présent (même catégorie, même texte arabe) est ignoré.
-- Généré par ops/contenus/athkar/make_migration.py à partir de docs/contenus/athkar-*.json.

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$, $q$Aʿoudhou billahi mina ch-chaytani r-radjim. Allahou la’a ilaha illa houwa l-hayyou l-qayyoumou la ta’khoudhouhou sinatoun wala nawmoun llahou ma fi s-samawati wama fi l-ardi man dha-lladhi yachfaʿou ʿindahou illa bi’idhnihi yaʿlamou ma bayna aydihim wama khalfahoum wala youhitouna bichay’in mmin ʿilmihi illa bima cha’a’a wasiʿa koursiyyouhou s-samawati wal-arda wala youdouhou hifdhouhouma wahouwa l-ʿaliyyou l-ʿadhim$q$, $q$Je cherche refuge auprès d’Allah contre Satan le maudit. « Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même (Al Qayyum). Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n’embrassent que ce qu’Il veut. Son Trône « Kursîy » déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, le Très-Grand . »$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 1. Coran 2:255 (Âyat al-Kursî). Renvoi du recueil : al-Hakim 1/562, jugé sahih par al-Albani (Sahih at-Targhib wa-t-Tarhib 1/273) ; attribué aussi à an-Nasa’i et at-Tabarani (chaîne de at-Tabarani : « bonne »).$q$, 1, 0, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$);

