SELECT $q$evening$q$, $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$, $q$Aʿoudhou billahi mina ch-chaytani r-radjim. Allahou la’a ilaha illa houwa l-hayyou l-qayyoumou la ta’khoudhouhou sinatoun wala nawmoun llahou ma fi s-samawati wama fi l-ardi man dha-lladhi yachfaʿou ʿindahou illa bi’idhnihi yaʿlamou ma bayna aydihim wama khalfahoum wala youhitouna bichay’in mmin ʿilmihi illa bima cha’a’a wasiʿa koursiyyouhou s-samawati wal-arda wala youdouhou hifdhouhouma wahouwa l-ʿaliyyou l-ʿadhim$q$, $q$Je cherche refuge auprès d’Allah contre Satan le maudit. « Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même (Al Qayyum). Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n’embrassent que ce qu’Il veut. Son Trône « Kursîy » déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, le Très-Grand . »$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 1. Coran 2:255 (Âyat al-Kursî). Renvoi du recueil : al-Hakim 1/562, jugé sahih par al-Albani (Sahih at-Targhib wa-t-Tarhib 1/273) ; attribué aussi à an-Nasa’i et at-Tabarani (chaîne de at-Tabarani : « bonne »).$q$, 1, 1, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ هُوَ ٱللَّهُ أَحَدٌ ٱللَّهُ ٱلصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ مِن شَرِّ مَا خَلَقَ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَٰهِ ٱلنَّاسِ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ﴾$q$, $q$Bismi llahi r-rahmani r-rahim. Qoul houwa llahou ahad. Allahou s-samad. Lam yalid walam youlad. Walam yakoun llahou koufouwan ahad. Bismi llahi r-rahmani r-rahim. Qoul aʿoudhou birabbi l-falaq. Min charri ma khalaq. Wamin charri ghasiqin idha waqab. Wamin charri n-naffathati fi l-ʿouqad. Wamin charri hasidin idha hasad. Bismi llahi r-rahmani r-rahim. Qoul aʿoudhou birabbi n-nas. Maliki n-nas. Ilahi n-nas. Min charri l-waswasi l-khannas. Alladhi youwaswisou fi soudouri n-nas. Mina l-djinnati wan-nas$q$, $q$Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis : "Il est Allah, Unique. Allah, Le Seul à être imploré pour ce que nous désirons. Il n’a jamais engendré, n’a pas été engendré non plus. Et nul n’est égal à Lui." » Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis: "Je cherche protection auprès du Seigneur de l’aube naissante, contre le mal des êtres qu’Il a créés, contre le mal de l’obscurité quand elle s’approfondit, contre le mal de celles qui soufflent (les sorcières) sur les nœuds, et contre le mal de l’envieux quand il envie ." » Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis : "Je cherche protection auprès du Seigneur des hommes. Le Souverain des hommes, Dieu des hommes, contre le mal du mauvais conseiller, furtif, qui insuffle des mauvaises pensées dans les poitrines des hommes, qu’il (le conseiller) soit un djinn, ou un être humain". » (trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 2. Coran 112, 113 et 114. Renvoi du recueil : Abu Dawud 4/322 ; at-Tirmidhi 5/567 (voir Sahih at-Tirmidhi 3/182). Le hadith précise : à dire trois fois le matin et le soir.$q$, 3, 2, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ هُوَ ٱللَّهُ أَحَدٌ ٱللَّهُ ٱلصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ مِن شَرِّ مَا خَلَقَ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَٰهِ ٱلنَّاسِ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ﴾$q$);

