INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ$q$, $q$Asbahna wa’asbaha l-moulkou lillahi, wal-hamdou lillahi, la ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou wahouwa ʿala koulli chay’in qadiroun, rabbi as’alouka khayra ma fi hadha l-yawmi wakhayra ma baʿdahou, wa’aʿoudhou bika min charri ma fi hadha l-yawmi wacharri ma baʿdahou, rabbi aʿoudhou bika mina l-kasali wasou’i l-kibari, rabbi aʿoudhou bika min ʿadhabin fi n-nari waʿadhabin fi l-qabr$q$, $q$Nous voici au matin et la royauté appartient à Allah. Louange à Allah. Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est Omnipotent. Seigneur, je Te demande le bien de ce jour et le bien de ce qui le suit, et je cherche refuge auprès de Toi contre le mal de ce jour et le mal de ce qui le suit. Seigneur, je cherche refuge auprès de Toi contre la paresse et la mauvaise vieillesse. Seigneur, je cherche refuge auprès de Toi contre un châtiment dans le Feu et un châtiment dans la tombe.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 3. Muslim 4/2088.$q$, 1, 4, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذَا الْيَوْمِ وَخَيْرَ مَا بَعْدَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذَا الْيَوْمِ وَشَرِّ مَا بَعْدَهُ، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ$q$, $q$Amsayna wa’amsa l-moulkou lillahi, wal-hamdou lillahi, la ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou wahouwa ʿala koulli chay’in qadiroun, rabbi as’alouka khayra ma fi hadhihi llaylati wakhayra ma baʿdaha, wa’aʿoudhou bika min charri ma fi hadhihi llaylati wacharri ma baʿdaha, rabbi aʿoudhou bika mina l-kasali wasou’i l-kibari, rabbi aʿoudhou bika min ʿadhabin fi n-nari waʿadhabin fi l-qabr$q$, $q$Nous voici au soir et la royauté appartient à Allah. Louange à Allah. Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est Omnipotent. Seigneur, je Te demande le bien de cette nuit et le bien de ce qui la suit, et je cherche refuge auprès de Toi contre le mal de cette nuit et le mal de ce qui la suit. Seigneur, je cherche refuge auprès de Toi contre la paresse et la mauvaise vieillesse. Seigneur, je cherche refuge auprès de Toi contre un châtiment dans le Feu et un châtiment dans la tombe.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 3. Muslim 4/2088.$q$, 1, 5, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ$q$, $q$Allahoumma bika asbahna, wabika amsayna, wabika nahya, wabika namoutou wa’ilayka n-nouchour$q$, $q$Ô Allah, c’est par Toi que nous atteignons le matin, par Toi que nous atteignons le soir, par Toi que nous vivons, par Toi que nous mourons, et c’est vers Toi que sera la résurrection.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 4. At-Tirmidhi 5/466 (voir Sahih at-Tirmidhi 3/142).$q$, 1, 6, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ$q$, $q$Allahoumma bika amsayna, wabika asbahna, wabika nahya, wabika namoutou wa’ilayka l-masir$q$, $q$Ô Allah, c’est par Toi que nous atteignons le soir, par Toi que nous atteignons le matin, par Toi que nous vivons, par Toi que nous mourons, et c’est vers Toi que sera le retour.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 4. At-Tirmidhi 5/466 (voir Sahih at-Tirmidhi 3/142).$q$, 1, 7, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ$q$, $q$Allahoumma anta rabbi la ilaha illa anta, khalaqtani wa’ana ʿabdouka, wa’ana ʿala ʿahdika wawaʿdika ma-stataʿtou, aʿoudhou bika min charri ma sanaʿtou, abou’ou laka biniʿmatika ʿalayya, wa’abou’ou bidhanbi faghfir li fa’innahou la yaghfirou dh-dhounouba illa ant$q$, $q$Ô Allah, Tu es mon Seigneur ; il n’y a de divinité digne d’adoration que Toi. Tu m’as créé et je suis Ton serviteur, et je me tiens à Ton engagement et à Ta promesse autant que je le peux. Je cherche refuge auprès de Toi contre le mal de ce que j’ai commis. Je reconnais Tes bienfaits envers moi et je reconnais mon péché ; pardonne-moi donc, car nul ne pardonne les péchés si ce n’est Toi.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 5. Sayyid al-istighfar. Al-Bukhari 7/150.$q$, 1, 8, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ$q$, $q$Allahoumma anta rabbi la ilaha illa anta, khalaqtani wa’ana ʿabdouka, wa’ana ʿala ʿahdika wawaʿdika ma-stataʿtou, aʿoudhou bika min charri ma sanaʿtou, abou’ou laka biniʿmatika ʿalayya, wa’abou’ou bidhanbi faghfir li fa’innahou la yaghfirou dh-dhounouba illa ant$q$, $q$Ô Allah, Tu es mon Seigneur ; il n’y a de divinité digne d’adoration que Toi. Tu m’as créé et je suis Ton serviteur, et je me tiens à Ton engagement et à Ta promesse autant que je le peux. Je cherche refuge auprès de Toi contre le mal de ce que j’ai commis. Je reconnais Tes bienfaits envers moi et je reconnais mon péché ; pardonne-moi donc, car nul ne pardonne les péchés si ce n’est Toi.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 5. Sayyid al-istighfar. Al-Bukhari 7/150.$q$, 1, 9, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلاَّ أَنْتَ، خَلَقْتَنِي وَأَنَا عَبْدُكَ، وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ، أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلاَئِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ$q$, $q$Allahoumma inni asbahtou ouchhidouka, wa’ouchhidou hamalata ʿarchika, wamala’ikatika, wadjamiʿa khalqika, annaka anta llahou la ilaha illa anta wahdaka la charika laka, wa’anna mouhammadan ʿabdouka warasoulouk$q$, $q$Ô Allah, ce matin, je Te prends à témoin, ainsi que les porteurs de Ton Trône, Tes anges et toute Ta création : Tu es Allah, il n’y a de divinité digne d’adoration que Toi, Seul, sans associé, et Muhammad est Ton serviteur et Ton messager. (quatre fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 6. Abu Dawud 4/317 ; al-Bukhari, al-Adab al-mufrad n° 1201 ; an-Nasa’i, ‘Amal al-yawm wa-l-layla n° 9 ; Ibn as-Sunni n° 70. Ibn Baz a jugé hassan la chaîne d’an-Nasa’i et d’Abu Dawud (Tuhfat al-akhyar p. 23).$q$, 4, 10, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلاَئِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$اللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلاَئِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ$q$, $q$Allahoumma inni amsaytou ouchhidouka, wa’ouchhidou hamalata ʿarchika, wamala’ikatika, wadjamiʿa khalqika, annaka anta llahou la ilaha illa anta wahdaka la charika laka, wa’anna mouhammadan ʿabdouka warasoulouk$q$, $q$Ô Allah, ce soir, je Te prends à témoin, ainsi que les porteurs de Ton Trône, Tes anges et toute Ta création : Tu es Allah, il n’y a de divinité digne d’adoration que Toi, Seul, sans associé, et Muhammad est Ton serviteur et Ton messager. (quatre fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 6. Abu Dawud 4/317 ; al-Bukhari, al-Adab al-mufrad n° 1201 ; an-Nasa’i, ‘Amal al-yawm wa-l-layla n° 9 ; Ibn as-Sunni n° 70. Ibn Baz a jugé hassan la chaîne d’an-Nasa’i et d’Abu Dawud (Tuhfat al-akhyar p. 23).$q$, 4, 11, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلاَئِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لاَ شَرِيكَ لَكَ، وَأَنَّ مُحَمَّداً عَبْدُكَ وَرَسُولُكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ$q$, $q$Allahoumma ma asbaha bi min niʿmatin aw bi’ahadin min khalqika faminka wahdaka la charika laka, falaka l-hamdou walaka ch-choukr$q$, $q$Ô Allah, le bienfait dont je jouis ce matin, ou dont jouit l’une de Tes créatures, vient de Toi seul, sans associé ; à Toi la louange et à Toi la reconnaissance.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 7. Abu Dawud 4/318 ; an-Nasa’i, ‘Amal al-yawm wa-l-layla n° 7 ; Ibn as-Sunni n° 41 ; Ibn Hibban (Mawarid) n° 2361. Ibn Baz a jugé hassan sa chaîne (Tuhfat al-akhyar p. 24).$q$, 1, 12, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$اللَّهُمَّ مَا أَمْسَى بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ$q$, $q$Allahoumma ma amsa bi min niʿmatin aw bi’ahadin min khalqika faminka wahdaka la charika laka, falaka l-hamdou walaka ch-choukr$q$, $q$Ô Allah, le bienfait dont je jouis ce soir, ou dont jouit l’une de Tes créatures, vient de Toi seul, sans associé ; à Toi la louange et à Toi la reconnaissance.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 7. Abu Dawud 4/318 ; an-Nasa’i, ‘Amal al-yawm wa-l-layla n° 7 ; Ibn as-Sunni n° 41 ; Ibn Hibban (Mawarid) n° 2361. Ibn Baz a jugé hassan sa chaîne (Tuhfat al-akhyar p. 24).$q$, 1, 13, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$اللَّهُمَّ مَا أَمْسَى بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لاَ شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لاَ إِلَهَ إِلاَّ أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ، وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لاَ إِلَهَ إِلاَّ أَنْتَ$q$, $q$Allahoumma ʿafini fi badani, Allahoumma ʿafini fi samʿi, Allahoumma ʿafini fi basari, la ilaha illa ant. Allahoumma inni aʿoudhou bika mina l-koufri, wal-faqri, wa’aʿoudhou bika min ʿadhabi l-qabri, la ilaha illa ant$q$, $q$Ô Allah, accorde-moi la santé dans mon corps ; ô Allah, accorde-moi la santé dans mon ouïe ; ô Allah, accorde-moi la santé dans ma vue ; il n’y a de divinité digne d’adoration que Toi. Ô Allah, je cherche refuge auprès de Toi contre l’incroyance et la pauvreté, et je cherche refuge auprès de Toi contre le châtiment de la tombe ; il n’y a de divinité digne d’adoration que Toi. (trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 8. Abu Dawud 4/324 ; Ahmad 5/42 ; an-Nasa’i, ‘Amal al-yawm wa-l-layla n° 22 ; Ibn as-Sunni n° 69 ; al-Bukhari, al-Adab al-mufrad. Ibn Baz a jugé hassan sa chaîne (Tuhfat al-akhyar p. 26).$q$, 3, 14, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$اللَّهُمَّ عَافِنِي فِي بَدَنِي، اللَّهُمَّ عَافِنِي فِي سَمْعِي، اللَّهُمَّ عَافِنِي فِي بَصَرِي، لاَ إِلَهَ إِلاَّ أَنْتَ. اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ، وَالْفَقْرِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، لاَ إِلَهَ إِلاَّ أَنْتَ$q$);

