INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ$q$, $q$Hasbiya llahou la ilaha illa houwa ʿalayhi tawakkaltou wahouwa rabbou l-ʿarchi l-ʿadhim$q$, $q$Allah me suffit ; il n’y a de divinité digne d’adoration que Lui ; en Lui je place ma confiance, et Il est le Seigneur du Trône immense. (sept fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 9. Ibn as-Sunni n° 71 (rapporté comme parole du Prophète) ; Abu Dawud 4/321 (rapporté comme parole d’un compagnon). Chaîne jugée sahih par Shu‘ayb et ‘Abd al-Qadir al-Arna’ut (voir Zad al-ma‘ad 2/376).$q$, 7, 16, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$حَسْبِيَ اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ$q$);

