SELECT $q$evening$q$, $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ: فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي$q$, $q$Allahoumma inni as’alouka l-ʿafwa wal-ʿafiyata fi d-dounya wal-’akhirati, Allahoumma inni as’alouka l-ʿafwa wal-ʿafiyata, fi dini wadounyaya wa’ahli, wamali, Allahoumma-stour ʿawrati, wa’amin rawʿati, Allahoumma-hfadhni min bayni yadayya, wamin khalfi, waʿan yamini, waʿan chimali, wamin fawqi, wa’aʿoudhou biʿadhamatika an oughtala min tahti$q$, $q$Ô Allah, je Te demande le pardon et la préservation (al-‘afiya) en ce bas monde et dans l’au-delà. Ô Allah, je Te demande le pardon et la préservation dans ma religion, ma vie d’ici-bas, ma famille et mes biens. Ô Allah, couvre mes défauts et apaise mes craintes. Ô Allah, protège-moi par devant, par derrière, à ma droite, à ma gauche et au-dessus de moi, et je cherche refuge auprès de Ta grandeur contre le fait d’être englouti par en dessous.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 10. Abu Dawud ; Ibn Majah (voir Sahih Ibn Majah 2/332).$q$, 1, 19, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالآخِرَةِ، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ: فِي دِينِي وَدُنْيَايَ وَأَهْلِي، وَمَالِي، اللَّهُمَّ اسْتُرْ عَوْرَاتِي، وَآمِنْ رَوْعَاتِي، اللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ، وَمِنْ خَلْفِي، وَعَنْ يَمِينِي، وَعَنْ شِمَالِي، وَمِنْ فَوْقِي، وَأَعُوذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِي$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشَرَكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ$q$, $q$Allahoumma ʿalima l-ghaybi wach-chahadati fatira s-samawati wal-ardi, rabba koulli chay’in wamalikahou, achhadou an la ilaha illa anta, aʿoudhou bika min charri nafsi, wamin charri ch-chaytani wacharakihi, wa’an aqtarifa ʿala nafsi sou’an, aw adjourrahou ila mouslim$q$, $q$Ô Allah, Connaisseur de l’invisible et du visible, Créateur des cieux et de la terre, Seigneur et Souverain de toute chose, j’atteste qu’il n’y a de divinité digne d’adoration que Toi. Je cherche refuge auprès de Toi contre le mal de mon âme, contre le mal de Satan et de ses pièges, et contre le fait de commettre un mal contre moi-même ou de l’attirer sur un musulman.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 11. At-Tirmidhi ; Abu Dawud (voir Sahih at-Tirmidhi 3/142). Note : le mot « sharak » (ses pièges) est lu aussi « shirk » (son polythéisme) selon les versions du hadith.$q$, 1, 20, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشَرَكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ$q$);

