INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ$q$, $q$Bismi llahi-lladhi la yadourrou maʿa-smihi chay’oun fi l-ardi wala fi s-sama’i wahouwa s-samiʿou l-ʿalim$q$, $q$Au nom d’Allah, avec le nom de Qui rien ne peut nuire, ni sur terre ni dans le ciel, et Il est l’Audient, l’Omniscient. (trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 12. Abu Dawud 4/323 ; at-Tirmidhi 5/465 ; Ibn Majah ; Ahmad (voir Sahih Ibn Majah 2/332). Ibn Baz a jugé hassan sa chaîne (Tuhfat al-akhyar p. 39).$q$, 3, 22, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$بِسْمِ اللَّهِ الَّذِي لاَ يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلاَ فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ$q$);

