INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$رَضِيتُ بِاللَّهِ رَبَّاً، وَبِالْإِسْلاَمِ دِيناً، وَبِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَبِيّاً$q$, $q$Raditou billahi rabban, wabil-islami dinan, wabimouhammadin salla llahou ʿalayhi wasallama nabiyya$q$, $q$Je suis satisfait d’Allah comme Seigneur, de l’Islam comme religion et de Muhammad ﷺ comme prophète. (trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 13. Ahmad 4/337 ; an-Nasa’i, ‘Amal al-yawm wa-l-layla n° 4 ; Ibn as-Sunni n° 68 ; Abu Dawud 4/418 ; at-Tirmidhi 5/465. Ibn Baz l’a jugé hassan (Tuhfat al-akhyar p. 39).$q$, 3, 24, false
