INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِيَ كُلَّهُ وَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ$q$, $q$Ya hayyou ya qayyoumou birahmatika astaghithou aslih li cha’niya koullahou wala takilni ila nafsi tarfata ʿayn$q$, $q$Ô Vivant, ô Celui qui subsiste par Lui-même, c’est Ta miséricorde que j’implore : améliore toute ma situation et ne me confie pas à moi-même, ne serait-ce que le temps d’un clin d’œil.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 14. Al-Hakim 1/545, jugé sahih et approuvé par adh-Dhahabi (voir Sahih at-Targhib wa-t-Tarhib 1/273).$q$, 1, 26, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِيَ كُلَّهُ وَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ$q$);

