SELECT $q$evening$q$, $q$يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِيَ كُلَّهُ وَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ$q$, $q$Ya hayyou ya qayyoumou birahmatika astaghithou aslih li cha’niya koullahou wala takilni ila nafsi tarfata ʿayn$q$, $q$Ô Vivant, ô Celui qui subsiste par Lui-même, c’est Ta miséricorde que j’implore : améliore toute ma situation et ne me confie pas à moi-même, ne serait-ce que le temps d’un clin d’œil.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 14. Al-Hakim 1/545, jugé sahih et approuvé par adh-Dhahabi (voir Sahih at-Targhib wa-t-Tarhib 1/273).$q$, 1, 27, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ أَصْلِحْ لِي شَأْنِيَ كُلَّهُ وَلاَ تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ:فَتْحَهُ، وَنَصْرَهُ، وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ$q$, $q$Asbahna wa’asbaha l-moulkou lillahi rabbi l-ʿalamina, Allahoumma inni as’alouka khayra hadha l-yawmi, fathahou, wanasrahou, wanourahou, wabarakatahou, wahoudahou, wa’aʿoudhou bika min charri ma fihi wacharri ma baʿdah$q$, $q$Nous voici au matin et la royauté appartient à Allah, Seigneur des mondes. Ô Allah, je Te demande le bien de ce jour : sa victoire, son aide, sa lumière, sa bénédiction et sa guidance ; et je cherche refuge auprès de Toi contre le mal de ce qu’il contient et le mal de ce qui le suit.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 15. Abu Dawud 4/322. Chaîne jugée hassan par Shu‘ayb et ‘Abd al-Qadir al-Arna’ut (Zad al-ma‘ad 2/273).$q$, 1, 28, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ:فَتْحَهُ، وَنَصْرَهُ، وَنُورَهُ، وَبَرَكَتَهُ، وَهُدَاهُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ: فَتْحَهَا، وَنَصْرَهَا، وَنُورَهَا، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهَا وَشَرِّ مَا بَعْدَهَا$q$, $q$Amsayna wa’amsa l-moulkou lillahi rabbi l-ʿalamina, Allahoumma inni as’alouka khayra hadhihi llaylati, fathaha, wanasraha, wanouraha, wabarakataha, wahoudaha, wa’aʿoudhou bika min charri ma fiha wacharri ma baʿdaha$q$, $q$Nous voici au soir et la royauté appartient à Allah, Seigneur des mondes. Ô Allah, je Te demande le bien de cette nuit : sa victoire, son aide, sa lumière, sa bénédiction et sa guidance ; et je cherche refuge auprès de Toi contre le mal de ce qu’elle contient et le mal de ce qui la suit.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 15. Abu Dawud 4/322. Chaîne jugée hassan par Shu‘ayb et ‘Abd al-Qadir al-Arna’ut (Zad al-ma‘ad 2/273).$q$, 1, 29, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ: فَتْحَهَا، وَنَصْرَهَا، وَنُورَهَا، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهَا وَشَرِّ مَا بَعْدَهَا$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلاَمِ، وَعَلَى كَلِمَةِ الْإِخْلاَصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ$q$, $q$Asbahna ʿala fitrati l-islami, waʿala kalimati l-ikhlasi, waʿala dini nabiyyina mouhammadin salla llahou ʿalayhi wasallama, waʿala millati abina ibrahima, hanifan mousliman wama kana mina l-mouchrikin$q$, $q$Nous voici au matin sur la nature originelle de l’Islam (fitra), sur la parole de la sincérité (kalimat al-ikhlas), sur la religion de notre Prophète Muhammad ﷺ et sur la voie de notre père Ibrahim, hanif et musulman, qui n’était pas du nombre des polythéistes.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 16. Ahmad 3/406-407 ; Ibn as-Sunni, ‘Amal al-yawm wa-l-layla n° 34 (voir Sahih al-Jami‘ 4/209).$q$, 1, 30, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$أَصْبَحْنَا عَلَى فِطْرَةِ الْإِسْلاَمِ، وَعَلَى كَلِمَةِ الْإِخْلاَصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلاَمِ، وَعَلَى كَلِمَةِ الْإِخْلاَصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ$q$, $q$Amsayna ʿala fitrati l-islami, waʿala kalimati l-ikhlasi, waʿala dini nabiyyina mouhammadin salla llahou ʿalayhi wasallama, waʿala millati abina ibrahima, hanifan mousliman wama kana mina l-mouchrikin$q$, $q$Nous voici au soir sur la nature originelle de l’Islam (fitra), sur la parole de la sincérité (kalimat al-ikhlas), sur la religion de notre Prophète Muhammad ﷺ et sur la voie de notre père Ibrahim, hanif et musulman, qui n’était pas du nombre des polythéistes.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 16. Ahmad 3/406-407 ; Ibn as-Sunni, ‘Amal al-yawm wa-l-layla n° 34 (voir Sahih al-Jami‘ 4/209).$q$, 1, 31, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلاَمِ، وَعَلَى كَلِمَةِ الْإِخْلاَصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفاً مُسْلِماً وَمَا كَانَ مِنَ الْمُشْرِكِينَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$سُبْحَانَ اللَّهِ وَبِحَمْدِهِ$q$, $q$Soubhana llahi wabihamdih$q$, $q$Gloire et pureté à Allah, et par Sa louange. (cent fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 17. Muslim 4/2071. Le hadith précise : cent fois le matin et le soir.$q$, 100, 32, false
