INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou, wahouwa ʿala koulli chay’in qadir$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est Omnipotent. (dix fois, ou une seule fois en cas de paresse)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 18. An-Nasa’i, ‘Amal al-yawm wa-l-layla n° 24 ; Abu Dawud 4/319 ; Ibn Majah ; Ahmad 4/60 (voir Sahih at-Targhib wa-t-Tarhib 1/270, Sahih Abi Dawud 3/957, Sahih Ibn Majah 2/331, Zad al-ma‘ad 2/377). Le rattachement des renvois à cette invocation est à confirmer.$q$, 10, 34, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$);

