INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$سُبْحَانَ اللَّهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ$q$, $q$Soubhana llahi wabihamdihi, ʿadada khalqihi, warida nafsihi, wazinata ʿarchihi, wamidada kalimatih$q$, $q$Gloire et pureté à Allah et par Sa louange, autant que le nombre de Ses créatures, autant que ce qui Le satisfait, autant que le poids de Son Trône et autant que l’encre de Ses paroles. (trois fois, le matin)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 20. Muslim 4/2090.$q$, 3, 37, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$سُبْحَانَ اللَّهِ وَبِحَمْدِهِ: عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$morning$q$, $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً$q$, $q$Allahoumma inni as’alouka ʿilman nafiʿan, warizqan tayyiban, waʿamalan moutaqabbala$q$, $q$Ô Allah, je Te demande une science utile, une subsistance pure et des œuvres acceptées. (le matin)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 21. Ibn as-Sunni n° 54 ; Ibn Majah n° 925. Chaîne jugée hassan par ‘Abd al-Qadir et Shu‘ayb al-Arna’ut (Zad al-ma‘ad 2/375).$q$, 1, 38, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$morning$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً$q$);

