SELECT $q$general$q$, $q$أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ$q$, $q$Astaghfirou llaha wa’atoubou ilayh$q$, $q$Je demande pardon à Allah et je me repens à Lui. (cent fois par jour)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 22. Al-Bukhari (avec Fath al-Bari 11/101) ; Muslim 4/2075.$q$, 100, 39, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$evening$q$, $q$أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ$q$, $q$Aʿoudhou bikalimati llahi t-tammati min charri ma khalaq$q$, $q$Je cherche refuge dans les paroles parfaites d’Allah contre le mal de ce qu’Il a créé. (trois fois, le soir)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Adhkar du matin et du soir », invocation n° 23. Ahmad 2/290 ; an-Nasa’i, ‘Amal al-yawm wa-l-layla n° 590 ; Ibn as-Sunni n° 68 (voir Sahih at-Tirmidhi 3/187, Sahih Ibn Majah 2/266, Tuhfat al-akhyar p. 45).$q$, 3, 40, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$evening$q$ AND text_ar = $q$أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ$q$);

