INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$اللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ$q$, $q$Allahoumma anta s-salamou, waminka s-salamou, tabarakta ya dha l-djalali wal-ikram$q$, $q$Ô Allah, Tu es la Paix et de Toi vient la paix. Béni sois-Tu, ô Seigneur de majesté et de générosité.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 1. Muslim 1/414.$q$, 1, 101, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$اللَّهُمَّ أَنْتَ السَّلاَمُ، وَمِنْكَ السَّلاَمُ، تَبَارَكْتَ يَا ذَا الْجَلاَلِ وَالْإِكْرَامِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou wahouwa ʿala koulli chay’in qadiroun, Allahoumma la maniʿa lima aʿtayta, wala mouʿtiya lima manaʿta, wala yanfaʿou dha l-djaddi minka l-djadd$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est Omnipotent. Ô Allah, nul ne peut empêcher ce que Tu accordes, nul ne peut accorder ce que Tu empêches, et l’opulence de l’opulent ne lui sert à rien auprès de Toi (ne le sauve pas de Toi).$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 2. Al-Bukhari 1/255 ; Muslim 1/414.$q$, 1, 102, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ، وَلاَ نَعْبُدُ إِلاَّ إِيَّاهُ, لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لاَ إِلَهَ إِلاَّ اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou, walahou l-hamdou, wahouwa ʿala koulli chay’in qadir. La hawla wala qouwwata illa billahi, la ilaha illa llahou, wala naʿboudou illa iyyahou, lahou n-niʿmatou walahou l-fadlou walahou th-thana’ou l-hasanou, la ilaha illa llahou moukhlisina lahou d-dina walaw kariha l-kafiroun$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est Omnipotent. Il n’y a de force ni de puissance qu’en Allah. Il n’y a de divinité digne d’adoration qu’Allah, et nous n’adorons que Lui. À Lui le bienfait, à Lui la grâce, à Lui la belle louange. Il n’y a de divinité digne d’adoration qu’Allah, Lui vouant un culte sincère, quand bien même les mécréants en seraient contrariés.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 3. Muslim 1/415.$q$, 1, 103, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ، لاَ إِلَهَ إِلاَّ اللَّهُ، وَلاَ نَعْبُدُ إِلاَّ إِيَّاهُ, لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ، لاَ إِلَهَ إِلاَّ اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$سُبْحَانَ اللَّهِ$q$, $q$Soubhana llah$q$, $q$Gloire et pureté à Allah. (trente-trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 4. Muslim 1/418. Le hadith précise : celui qui dit cela après chaque prière, ses péchés sont pardonnés même s’ils étaient comme l’écume de la mer.$q$, 33, 104, false
