INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou wahouwa ʿala koulli chay’in qadir$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est Omnipotent. (pour compléter la centaine)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 4. Muslim 1/418 (pour compléter la centaine).$q$, 1, 107, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ هُوَ ٱللَّهُ أَحَدٌ ٱللَّهُ ٱلصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ مِن شَرِّ مَا خَلَقَ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَٰهِ ٱلنَّاسِ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ﴾$q$, $q$Bismi llahi r-rahmani r-rahim. Qoul houwa llahou ahad. Allahou s-samad. Lam yalid walam youlad. Walam yakoun llahou koufouwan ahad. Bismi llahi r-rahmani r-rahim. Qoul aʿoudhou birabbi l-falaq. Min charri ma khalaq. Wamin charri ghasiqin idha waqab. Wamin charri n-naffathati fi l-ʿouqad. Wamin charri hasidin idha hasad. Bismi llahi r-rahmani r-rahim. Qoul aʿoudhou birabbi n-nas. Maliki n-nas. Ilahi n-nas. Min charri l-waswasi l-khannas. Alladhi youwaswisou fi soudouri n-nas. Mina l-djinnati wan-nas$q$, $q$Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis : "Il est Allah, Unique. Allah, Le Seul à être imploré pour ce que nous désirons. Il n’a jamais engendré, n’a pas été engendré non plus. Et nul n’est égal à Lui." » Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis: "Je cherche protection auprès du Seigneur de l’aube naissante, contre le mal des êtres qu’Il a créés, contre le mal de l’obscurité quand elle s’approfondit, contre le mal de celles qui soufflent (les sorcières) sur les nœuds, et contre le mal de l’envieux quand il envie ." » Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis : "Je cherche protection auprès du Seigneur des hommes. Le Souverain des hommes, Dieu des hommes, contre le mal du mauvais conseiller, furtif, qui insuffle des mauvaises pensées dans les poitrines des hommes, qu’il (le conseiller) soit un djinn, ou un être humain". » (après chaque prière)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 5. Coran 112, 113 et 114. Abu Dawud 2/86 ; an-Nasa’i 3/68 (voir Sahih at-Tirmidhi 2/8 ; Fath al-Bari 9/62). Ces trois sourates sont appelées « al-Mu‘awwidhat ».$q$, 1, 108, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ هُوَ ٱللَّهُ أَحَدٌ ٱللَّهُ ٱلصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ مِن شَرِّ مَا خَلَقَ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَٰهِ ٱلنَّاسِ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ﴾$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$, $q$Allahou la’a ilaha illa houwa l-hayyou l-qayyoumou la ta’khoudhouhou sinatoun wala nawmoun llahou ma fi s-samawati wama fi l-ardi man dha-lladhi yachfaʿou ʿindahou illa bi’idhnihi yaʿlamou ma bayna aydihim wama khalfahoum wala youhitouna bichay’in mmin ʿilmihi illa bima cha’a’a wasiʿa koursiyyouhou s-samawati wal-arda wala youdouhou hifdhouhouma wahouwa l-ʿaliyyou l-ʿadhim$q$, $q$« Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même (Al Qayyum). Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n’embrassent que ce qu’Il veut. Son Trône « Kursîy » déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, le Très-Grand . » (après chaque prière)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 6. Coran 2:255. An-Nasa’i, ‘Amal al-yawm wa-l-layla n° 100 ; Ibn as-Sunni n° 121, jugé sahih (Sahih al-Jami‘ 5/339 ; as-Silsila as-sahiha 2/697 n° 972). Le hadith précise : celui qui la récite après chaque prière, rien ne l’empêche d’entrer au Paradis sauf la mort.$q$, 1, 109, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou youhyi wayoumitou wahouwa ʿala koulli chay’in qadir$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange ; Il donne la vie et la mort, et Il est Omnipotent. (dix fois, après la prière du Maghrib et celle du Fajr)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 7. At-Tirmidhi 5/515 ; Ahmad 4/227 (voir Zad al-ma‘ad 1/300).$q$, 10, 110, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$after_prayer$q$, $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً$q$, $q$Allahoumma inni as’alouka ʿilman nafiʿan, warizqan tayyiban, waʿamalan moutaqabbala$q$, $q$Ô Allah, je Te demande une science utile, une subsistance pure et des œuvres acceptées. (après le salut de la prière du Fajr)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr après le salut de la prière », invocation n° 8. Ibn Majah et d’autres (voir Sahih Ibn Majah 1/152 ; Majma‘ az-zawa’id 10/111).$q$, 1, 111, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$after_prayer$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْماً نَافِعاً، وَرِزْقاً طَيِّباً، وَعَمَلاً مُتَقَبَّلاً$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ هُوَ ٱللَّهُ أَحَدٌ ٱللَّهُ ٱلصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ مِن شَرِّ مَا خَلَقَ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَٰهِ ٱلنَّاسِ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ﴾$q$, $q$Bismi llahi r-rahmani r-rahim. Qoul houwa llahou ahad. Allahou s-samad. Lam yalid walam youlad. Walam yakoun llahou koufouwan ahad. Bismi llahi r-rahmani r-rahim. Qoul aʿoudhou birabbi l-falaq. Min charri ma khalaq. Wamin charri ghasiqin idha waqab. Wamin charri n-naffathati fi l-ʿouqad. Wamin charri hasidin idha hasad. Bismi llahi r-rahmani r-rahim. Qoul aʿoudhou birabbi n-nas. Maliki n-nas. Ilahi n-nas. Min charri l-waswasi l-khannas. Alladhi youwaswisou fi soudouri n-nas. Mina l-djinnati wan-nas$q$, $q$En se couchant : joindre les paumes, souffler dedans en récitant ce qui suit, puis se passer les mains sur le corps autant qu’on le peut, en commençant par la tête, le visage et le devant du corps ; trois fois. Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis : "Il est Allah, Unique. Allah, Le Seul à être imploré pour ce que nous désirons. Il n’a jamais engendré, n’a pas été engendré non plus. Et nul n’est égal à Lui." » Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis: "Je cherche protection auprès du Seigneur de l’aube naissante, contre le mal des êtres qu’Il a créés, contre le mal de l’obscurité quand elle s’approfondit, contre le mal de celles qui soufflent (les sorcières) sur les nœuds, et contre le mal de l’envieux quand il envie ." » Au nom d’Allah, le Tout Miséricordieux, le Très Miséricordieux. « Dis : "Je cherche protection auprès du Seigneur des hommes. Le Souverain des hommes, Dieu des hommes, contre le mal du mauvais conseiller, furtif, qui insuffle des mauvaises pensées dans les poitrines des hommes, qu’il (le conseiller) soit un djinn, ou un être humain". »$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 1. Coran 112, 113 et 114. Al-Bukhari avec Fath al-Bari 9/62 ; Muslim 4/1723.$q$, 3, 112, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ هُوَ ٱللَّهُ أَحَدٌ ٱللَّهُ ٱلصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ مِن شَرِّ مَا خَلَقَ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ﴾ بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ ﴿قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ مَلِكِ ٱلنَّاسِ إِلَٰهِ ٱلنَّاسِ مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ﴾$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$, $q$Allahou la’a ilaha illa houwa l-hayyou l-qayyoumou la ta’khoudhouhou sinatoun wala nawmoun llahou ma fi s-samawati wama fi l-ardi man dha-lladhi yachfaʿou ʿindahou illa bi’idhnihi yaʿlamou ma bayna aydihim wama khalfahoum wala youhitouna bichay’in mmin ʿilmihi illa bima cha’a’a wasiʿa koursiyyouhou s-samawati wal-arda wala youdouhou hifdhouhouma wahouwa l-ʿaliyyou l-ʿadhim$q$, $q$« Allah! Point de divinité à part Lui, le Vivant, Celui qui subsiste par Lui-même (Al Qayyum). Ni somnolence ni sommeil ne Le saisissent. A Lui appartient tout ce qui est dans les cieux et sur la terre. Qui peut intercéder auprès de Lui sans Sa permission? Il connaît leur passé et leur futur. Et, de Sa science, ils n’embrassent que ce qu’Il veut. Son Trône « Kursîy » déborde les cieux et la terre, dont la garde ne Lui coûte aucune peine. Et Il est le Très-Haut, le Très-Grand . »$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 2. Coran 2:255. Al-Bukhari avec Fath al-Bari 4/487. Le hadith précise : celui qui la récite en se couchant aura un gardien d’Allah auprès de lui et Satan ne l’approchera pas jusqu’au matin.$q$, 1, 113, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ﴾$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$﴿ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ﴾$q$, $q$Amana r-rasoulou bima’a ounzila ilayhi min rrabbihi wal-mou’minouna koulloun amana billahi wamala’ikatihi wakoutoubihi warousoulihi la noufarriqou bayna ahadin mmin rrousoulihi waqalou samiʿna wa’ataʿna ghoufranaka rabbana wa’ilayka l-masir. La youkallifou llahou nafsan illa wousʿaha laha ma kasabat waʿalayha ma-ktasabat rabbana la tou’akhidhna’a in nnasina’a aw akhta’na rabbana wala tahmil ʿalayna’a isran kama hamaltahou ʿala-lladhina min qablina rabbana wala touhammilna ma la taqata lana bihi waʿfou ʿanna waghfir lana warhamna’a anta mawlana fansourna ʿala l-qawmi l-kafirin$q$, $q$« Le Messager a cru en ce qu’on a fait descendre vers lui venant de son Seigneur, et aussi les croyants: tous ont cru en Allah, en Ses Anges, à Ses Livres et en Ses Messagers (en disant): “Nous ne faisons aucune distinction entre Ses Messagers.” Et ils ont dit: “Nous avons entendu et obéi. Seigneur! Nous implorons Ton pardon. C’est vers Toi que sera le retour.” Allah n’impose à aucune âme une charge supérieure à sa capacité. Elle sera récompensée du bien qu’elle aura fait, punie du mal qu’elle aura fait." Seigneur ! Ne nous châtie pas s’il nous arrive d’oublier ou de commettre une erreur. Seigneur ! Ne nous charge pas d’un fardeau lourd comme Tu as chargé ceux qui vécurent avant nous. Seigneur ! Ne nous impose pas ce que nous ne pouvons supporter, efface nos fautes, pardonne-nous et fais nous miséricorde. Tu es Notre Maître, accorde-nous donc la victoire sur les peuples infidèles ." »$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 3. Coran 2:285-286. Al-Bukhari avec Fath al-Bari 9/94 ; Muslim 1/554. Le hadith précise : celui qui les récite pendant la nuit, elles lui suffisent.$q$, 1, 114, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$﴿ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ﴾$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ$q$, $q$Bismika rabbi wadaʿtou djanbi, wabika arfaʿouhou, fa’in amsakta nafsi farhamha, wa’in arsaltaha fahfadhha, bima tahfadhou bihi ʿibadaka s-salihin$q$, $q$C’est en Ton nom, mon Seigneur, que j’ai posé mon flanc, et c’est par Toi que je le relèverai. Si Tu retiens mon âme, aie pitié d’elle ; et si Tu la renvoies, protège-la comme Tu protèges Tes serviteurs vertueux.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 4. Al-Bukhari 11/126 ; Muslim 4/2084.$q$, 1, 115, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِن أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا. اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ$q$, $q$Allahoumma innaka khalaqta nafsi wa’anta tawaffaha, laka mamatouha wamahyaha, in ahyaytaha fahfadhha, wa’in amattaha faghfir laha. Allahoumma inni as’alouka l-ʿafiyah$q$, $q$Ô Allah, c’est Toi qui as créé mon âme et c’est Toi qui la rappelles à Toi ; sa mort et sa vie T’appartiennent. Si Tu lui accordes la vie, protège-la ; si Tu la fais mourir, pardonne-lui. Ô Allah, je Te demande la préservation (al-‘afiya).$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 5. Muslim 4/2083 ; Ahmad 2/79.$q$, 1, 116, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا. اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ$q$, $q$Allahoumma qini ʿadhabaka yawma tabʿathou ʿibadak$q$, $q$Ô Allah, préserve-moi de Ton châtiment le jour où Tu ressusciteras Tes serviteurs. (trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 6. Abu Dawud 4/311 (voir Sahih at-Tirmidhi 3/143). Le recueil place cette invocation après avoir posé la main droite sous la joue.$q$, 3, 117, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا$q$, $q$Bismika llahoumma amoutou wa’ahya$q$, $q$C’est en Ton nom, ô Allah, que je meurs et que je vis.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 7. Al-Bukhari avec Fath al-Bari 11/113 ; Muslim 4/2083.$q$, 1, 118, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$سُبْحَانَ اللَّهِ$q$, $q$Soubhana llah$q$, $q$Gloire et pureté à Allah. (trente-trois fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 8. Al-Bukhari avec Fath al-Bari 7/71 ; Muslim 4/2091. Le hadith précise : cela vaut mieux, pour celui qui le dit en se couchant, qu’un serviteur.$q$, 33, 119, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$سُبْحَانَ اللَّهِ$q$);

