SELECT $q$sleep$q$, $q$اللَّهُ أَكْبَرُ$q$, $q$Allahou akbar$q$, $q$Allah est le Plus Grand. (trente-quatre fois)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 8. Al-Bukhari avec Fath al-Bari 7/71 ; Muslim 4/2091 (suite de la précédente).$q$, 34, 121, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$اللَّهُ أَكْبَرُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ$q$, $q$Allahoumma rabba s-samawati s-sabʿi warabba l-ardi, warabba l-ʿarchi l-ʿadhimi, rabbana warabba koulli chay’in, faliqa l-habbi wan-nawa, wamounzila t-tawrati wal-indjili, wal-fourqani, aʿoudhou bika min charri koulli chay’in anta akhidhoun binasiyatih. Allahoumma anta l-awwalou falaysa qablaka chay’oun, wa’anta l-’akhirou falaysa baʿdaka chay’oun, wa’anta dh-dhahirou falaysa fawqaka chay’oun, wa’anta l-batinou falaysa dounaka chay’oun, iqdi ʿanna d-dayna wa’aghnina mina l-faqr$q$, $q$Ô Allah, Seigneur des sept cieux, Seigneur de la terre et Seigneur du Trône immense, notre Seigneur et Seigneur de toute chose, Toi qui fends le grain et le noyau, qui as fait descendre la Torah, l’Évangile et le Discernement (al-Furqan), je cherche refuge auprès de Toi contre le mal de toute chose dont Tu tiens le toupet. Ô Allah, Tu es le Premier : rien n’est avant Toi ; Tu es le Dernier : rien n’est après Toi ; Tu es l’Apparent : rien n’est au-dessus de Toi ; Tu es le Caché : rien n’est en deçà de Toi. Acquitte nos dettes et enrichis-nous contre la pauvreté.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 9. Muslim 4/2084.$q$, 1, 122, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$اللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لاَ كَافِيَ لَهُ وَلاَ مُؤْوِيَ$q$, $q$Al-hamdou lillahi-lladhi atʿamana wasaqana, wakafana, wa’awana, fakam mimman la kafiya lahou wala mou’wiya$q$, $q$Louange à Allah qui nous a donné à manger et à boire, qui nous a suffi et nous a abrités. Combien de gens n’ont personne pour leur suffire ni pour les abriter !$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 10. Muslim 4/2085.$q$, 1, 123, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا، وَآوَانَا، فَكَمْ مِمَّنْ لاَ كَافِيَ لَهُ وَلاَ مُؤْوِيَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ$q$, $q$Allahoumma ʿalima l-ghaybi wach-chahadati fatira s-samawati wal-ardi, rabba koulli chay’in wamalikahou, achhadou an la ilaha illa anta, aʿoudhou bika min charri nafsi, wamin charri ch-chaytani wachirkihi, wa’an aqtarifa ʿala nafsi sou’an, aw adjourrahou ila mouslim$q$, $q$Ô Allah, Connaisseur de l’invisible et du visible, Créateur des cieux et de la terre, Seigneur et Souverain de toute chose, j’atteste qu’il n’y a de divinité digne d’adoration que Toi. Je cherche refuge auprès de Toi contre le mal de mon âme, contre le mal de Satan et de son polythéisme (shirk), et contre le fait de commettre un mal contre moi-même ou de l’attirer sur un musulman.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 11. Abu Dawud 4/317 (voir Sahih at-Tirmidhi 3/142). Note : la version du matin lit « sharakihi » (ses pièges), celle-ci « shirkihi » (son polythéisme), telles que données par le recueil.$q$, 1, 124, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$اللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوءاً، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$سُورَةُ السَّجْدَةِ، وَسُورَةُ الْمُلْكِ$q$, $q$Souratou s-sadjdati, wasouratou l-moulk$q$, $q$Réciter la sourate As-Sajda (32), puis la sourate Al-Mulk (67).$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 12. At-Tirmidhi et an-Nasa’i (voir Sahih al-Jami‘ 4/255). Le recueil donne l’indication « il récite Alif Lam Mim Tanzil (as-Sajda) et Tabarak alladhi biyadihi l-mulk ». Les noms de sourates sont écrits ici par l’assistant : à vérifier.$q$, 1, 125, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$سُورَةُ السَّجْدَةِ، وَسُورَةُ الْمُلْكِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$sleep$q$, $q$اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ$q$, $q$Allahoumma aslamtou nafsi ilayka, wafawwadtou amri ilayka, wawadjdjahtou wadjhi ilayka, wa’aldja’tou dhahri ilayka, raghbatan warahbatan ilayka, la maldja’a wala mandja minka illa ilayka, amantou bikitabika-lladhi anzalta, wabinabiyyika-lladhi arsalt$q$, $q$Ô Allah, je me soumets à Toi, je Te confie mon affaire, je tourne mon visage vers Toi, j’adosse mon dos à Toi, par désir et par crainte de Toi. Il n’y a de refuge ni de salut contre Toi qu’auprès de Toi. Je crois en Ton Livre que Tu as révélé et en Ton prophète que Tu as envoyé.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr du sommeil », invocation n° 13. Al-Bukhari avec Fath al-Bari 11/113 ; Muslim 4/2081. Le hadith précise : si tu meurs cette nuit-là, tu meurs sur la fitra (la nature originelle).$q$, 1, 126, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$sleep$q$ AND text_ar = $q$اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ$q$, $q$Al-hamdou lillahi-lladhi ahyana baʿda ma amatana, wa’ilayhi n-nouchour$q$, $q$Louange à Allah qui nous a rendu la vie après nous avoir fait mourir (le sommeil), et c’est vers Lui que sera la résurrection. (au réveil)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr au réveil », invocation n° 1. Al-Bukhari avec Fath al-Bari 11/113 ; Muslim 4/2083.$q$, 1, 127, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفِرْ لِي$q$, $q$La ilaha illa llahou wahdahou la charika lahou, lahou l-moulkou walahou l-hamdou, wahouwa ʿala koulli chay’in qadiroun, soubhana llahi, wal-hamdou lillahi, wala ilaha illa llahou, wallahou akbarou, wala hawla wala qouwwata illa billahi l-ʿaliyyi l-ʿadhimi, rabbi-ghfir li$q$, $q$Il n’y a de divinité digne d’adoration qu’Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est Omnipotent. Gloire et pureté à Allah, louange à Allah, il n’y a de divinité digne d’adoration qu’Allah, Allah est le Plus Grand, et il n’y a de force ni de puissance qu’en Allah, le Très Haut, l’Immense. Seigneur, pardonne-moi. (au réveil pendant la nuit)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr au réveil », invocation n° 2. Al-Bukhari avec Fath al-Bari 3/144 et d’autres ; formulation d’Ibn Majah (voir Sahih Ibn Majah 2/335). Le recueil rapporte : celui qui se réveille la nuit et dit cela, puis demande pardon ou invoque, est exaucé ; s’il fait ses ablutions et prie, sa prière est acceptée.$q$, 1, 128, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفِرْ لِي$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ$q$, $q$Al-hamdou lillahi-lladhi ʿafani fi djasadi, waradda ʿalayya rouhi, wa’adhina li bidhikrih$q$, $q$Louange à Allah qui m’a donné la santé dans mon corps, m’a rendu mon âme et m’a permis de L’invoquer. (au réveil)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr au réveil », invocation n° 3. At-Tirmidhi 5/473 (voir Sahih at-Tirmidhi 3/144).$q$, 1, 129, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لِي بِذِكْرِهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$﴿إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ بَعْضُكُم مِّنۢ بَعْضٍ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ مَتَٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾$q$, $q$Inna fi khalqi s-samawati wal-ardi wakhtilafi-llayli wan-nahari layatin lli’ouli l-albab. Alladhina yadhkourouna llaha qiyaman waqouʿoudan waʿala djounoubihim wayatafakkarouna fi khalqi s-samawati wal-ardi rabbana ma khalaqta hadha batilan soubhanaka faqina ʿadhaba n-nar. Rabbana’a innaka man toudkhili n-nara faqad akhzaytahou wama lildhdhalimina min ansar. Rrabbana’a innana samiʿna mounadiyan younadi lil’imani an aminou birabbikoum famanna rabbana faghfir lana dhounoubana wakaffir ʿanna sayyatina watawaffana maʿa l-abrar. Rabbana wa’atina ma waʿadttana ʿala rousoulika wala toukhzina yawma l-qiyamati innaka la toukhlifou l-miʿad. Fastadjaba lahoum rabbouhoum anni la’a oudiʿou ʿamala ʿamilin mminkoum mmin dhakarin aw ountha baʿdoukoum mmin baʿdin falladhina hadjarou wa’oukhridjou min diyarihim wa’oudhou fi sabili waqatalou waqoutilou la’oukaffiranna ʿanhoum sayyatihim wala’oudkhilannahoum djannatin tadjri min tahtiha l-anharou thawaban mmin ʿindi llahi wallahou ʿindahou housnou th-thawab. La yaghourrannaka taqalloubou-lladhina kafarou fi l-bilad. Mataʿoun qaliloun thoumma ma’wahoum djahannamou wabi’sa l-mihad. Lakini-lladhina-ttaqaw rabbahoum lahoum djannatoun tadjri min tahtiha l-anharou khalidina fiha nouzoulan mmin ʿindi llahi wama ʿinda llahi khayroun llil’abrar. Wa’inna min ahli l-kitabi laman you’minou billahi wama’a ounzila ilaykoum wama’a ounzila ilayhim khachiʿina lillahi la yachtarouna bayati llahi thamanan qalilan oula’ika lahoum adjrouhoum ʿinda rabbihim inna llaha sariʿou l-hisab. Ya’ayyouha-lladhina amanou-sbirou wasabirou warabitou wattaqou llaha laʿallakoum touflihoun$q$, $q$« En vérité, dans la création des cieux et de la terre, et dans l’alternance de la nuit et du jour, il y a certes des signes pour les doués d’intelligence, qui, debout, assis, couchés sur leurs côtés, invoquent Allah et méditent sur la création des cieux et de la terre (disant): “ Notre Seigneur! Tu n’as pas créé cela en vain. Gloire à Toi! Épargne-nous du châtiment du Feu. Seigneur! Quiconque Tu fais entrer dans le Feu, Tu le couvres vraiment d’ignominie. Et pour les injustes, il n’y aura pas de secoureurs! Seigneur! Nous avons entendu l’appel de celui qui a appelé ainsi à la foi: "Croyez en votre Seigneur !" Et dès lors nous avons cru. Seigneur ! Pardonne-nous nos péchés, efface de nous nos méfaits, et place nous, à notre mort, avec les gens de bien. Seigneur! Donne-nous ce que Tu nous as promis par Tes Messagers. Et ne nous couvre pas d’ignominie au Jour de la Résurrection. Car Toi, Tu ne manques pas à Ta promesse". Leur Seigneur les a alors exaucés (disant) : "En vérité, Je ne laisse pas perdre le bien que quiconque parmi vous a fait, homme ou femme, car vous êtes les uns des autres. Donc, ceux qui ont émigré, qui ont été expulsés de leurs demeures, qui ont été persécutés dans Mon chemin, qui ont combattu, qui ont été tués, Je tiendrai certes pour expiées leurs mauvaises actions, et les ferai entrer dans les Jardins sous lesquels coulent les ruisseaux, comme récompense de la part d’Allah ." Quant à Allah, c’est auprès de Lui qu’est la plus belle récompense. Que ne t’abuse point la versatilité [pour la prospérité] dans le pays, de ceux qui sont infidèles. Piètre jouissance! Puis leur refuge sera l’Enfer. Et quelle détestable couche ! Mais quant à ceux qui craignent leur Seigneur, ils auront des Jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement, un lieu d’accueil de la part d’Allah. Et ce qu’il y a auprès d’Allah est meilleur, pour les pieux. Il y a certes, parmi les gens du Livre ceux qui croient en Allah et en ce qu’on a fait descendre vers vous et en ceux qu’on a fait descendre vers eux. Ils sont humbles envers Allah, et ne vendent point les versets d’Allah à vil prix. Voilà ceux dont la récompense est auprès de leur Seigneur. En vérité, Allah est prompt à faire les comptes. Ô les croyants! Soyez endurants. Incitez-vous à l’endurance. Luttez constamment (contre l’ennemi) et craignez Allah, afin que vous réussissiez! »$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Dhikr au réveil », invocation n° 4. Coran 3:190-200. Al-Bukhari avec Fath al-Bari 8/238 ; Muslim 1/530.$q$, 1, 130, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$﴿إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَٰتٍ لِّأُو۟لِى ٱلْأَلْبَٰبِ ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَٰطِلًا سُبْحَٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِى لِلْإِيمَٰنِ أَنْ ءَامِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا رَبَّنَا فَٱغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّـَٔاتِنَا وَتَوَفَّنَا مَعَ ٱلْأَبْرَارِ رَبَّنَا وَءَاتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ ٱلْقِيَٰمَةِ إِنَّكَ لَا تُخْلِفُ ٱلْمِيعَادَ فَٱسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّى لَآ أُضِيعُ عَمَلَ عَٰمِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ بَعْضُكُم مِّنۢ بَعْضٍ فَٱلَّذِينَ هَاجَرُوا۟ وَأُخْرِجُوا۟ مِن دِيَٰرِهِمْ وَأُوذُوا۟ فِى سَبِيلِى وَقَٰتَلُوا۟ وَقُتِلُوا۟ لَأُكَفِّرَنَّ عَنْهُمْ سَيِّـَٔاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ ثَوَابًا مِّنْ عِندِ ٱللَّهِ وَٱللَّهُ عِندَهُۥ حُسْنُ ٱلثَّوَابِ لَا يَغُرَّنَّكَ تَقَلُّبُ ٱلَّذِينَ كَفَرُوا۟ فِى ٱلْبِلَٰدِ مَتَٰعٌ قَلِيلٌ ثُمَّ مَأْوَىٰهُمْ جَهَنَّمُ وَبِئْسَ ٱلْمِهَادُ لَٰكِنِ ٱلَّذِينَ ٱتَّقَوْا۟ رَبَّهُمْ لَهُمْ جَنَّٰتٌ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ خَٰلِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ ٱللَّهِ وَمَا عِندَ ٱللَّهِ خَيْرٌ لِّلْأَبْرَارِ وَإِنَّ مِنْ أَهْلِ ٱلْكِتَٰبِ لَمَن يُؤْمِنُ بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْكُمْ وَمَآ أُنزِلَ إِلَيْهِمْ خَٰشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِـَٔايَٰتِ ٱللَّهِ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ إِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱصْبِرُوا۟ وَصَابِرُوا۟ وَرَابِطُوا۟ وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾$q$);
